mapper.select:
SELECT notice_id, recipient_id, comment_id, article_id, sender_id, type, is_read, create_time, deleted_at FROM comment_notices WHERE recipient_id = #{recipientId} AND deleted_at IS NULL
AND (create_time < #{cursorCreateTime} OR (create_time = #{cursorCreateTime} AND notice_id < #{cursorNoticeId}))
ORDER BY create_time DESC, notice_id DESC LIMIT #{limit}

mapper.update:
UPDATE comment_notices SET is_read = TRUE WHERE recipient_id = #{recipientId} AND is_read = FALSE AND deleted_at IS NULL
AND notice_id IN
#{noticeId}
